        b = self._empty_board()
        b[0][0] = '5'; b[0][1] = '5'
        self.assertFalse(is_valid_sudoku(b))
    def test_box_conflict(self):
        b = self._empty_board()
        b[0][0] = '3'; b[1][1] = '3'
        self.assertFalse(is_valid_sudoku(b))
    def test_no_conflict(self):
        b = self._empty_board()
        b[0][0] = '5'; b[1][0] = '3'
        self.assertTrue(is_valid_sudoku(b))

